            int p = parent[x];
            parent[x] = find(p);
            parity[x] ^= parity[p];
        }
        return parent[x];
    }

    static boolean union(int a, int b, int requiredParity) {
        int rootA = find(a);
        int parityA = parity[a];
        int rootB = find(b);
        int parityB = parity[b];

        if (rootA == rootB) {
            return (parityA ^ parityB) == requiredParity;
        }

        if (size[rootA] < size[rootB]) {
            parent[rootA] = rootB;
            parity[rootA] = parityA ^ parityB ^ requiredParity;
            size[rootB] += size[rootA];
        } else {
            parent[rootB] = rootA;
            parity[rootB] = parityA ^ parityB ^ requiredParity;
            size[rootA] += size[rootB];
        }
        return true;
    }

    static int findNext(int[] next, int x) {
        int root = x;
        while (next[root] != root) {
            root = next[root];
        }

        while (next[x] != x) {
            int p = next[x];
            next[x] = root;
            x = p;
        }
        return root;
    }

    static boolean uniteRange(int[] order, int left, int right, int[] next) {
        int edge = findNext(next, left);
        while (edge < right) {
            if (!union(order[edge], order[edge + 1], 0)) {
                return false;
            }
            next[edge] = findNext(next, edge + 1);
            edge = findNext(next, edge);
        }
        return true;
    }

    static boolean processDimension(int[] order, int[] coordinate, int[] next, long distance) {
        int prefixEnd = 0;
        int groupStart = 0;

        while (groupStart < n) {
            int value = coordinate[order[groupStart]];
            long threshold = (long) value - distance;

            while (prefixEnd < n && coordinate[order[prefixEnd]] < threshold) {
                prefixEnd++;
            }

            int groupEnd = groupStart + 1;
            while (groupEnd < n && coordinate[order[groupEnd]] == value) {
                groupEnd++;
            }

            if (prefixEnd > 0) {
                if (!uniteRange(order, 0, prefixEnd - 1, next)) {
                    return false;
                }
                if (!uniteRange(order, groupStart, n - 1, next)) {
                    return false;
                }
                if (!union(order[prefixEnd - 1], order[groupStart], 1)) {
                    return false;
                }
            }

            groupStart = groupEnd;
        }
        return true;
    }

